const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const q = tok[0];
const LO = -1000000, HI = 1000000;
const slope = [], icpt = [], left = [], right = [];
function add(m, b) {
  if (slope.length === 0) { slope.push(m); icpt.push(b); left.push(-1); right.push(-1); return; }
  let node = 0, lo = LO, hi = HI;
  for (;;) {
    const mid = (lo + hi) >> 1;
    if (m * mid + b > slope[node] * mid + icpt[node]) {
      [slope[node], m] = [m, slope[node]];
      [icpt[node], b] = [b, icpt[node]];
    }
    if (lo === hi) return;
    let side;
    if (m * lo + b > slope[node] * lo + icpt[node]) { side = left; hi = mid; }
    else if (m * hi + b > slope[node] * hi + icpt[node]) { side = right; lo = mid + 1; }
    else return;
    if (side[node] === -1) {
      slope.push(m); icpt.push(b); left.push(-1); right.push(-1);
      side[node] = slope.length - 1;
      return;
    }
    node = side[node];
  }
}
function query(x) {
  let node = 0, lo = LO, hi = HI, best = -Infinity;
  while (node !== -1) {
    const v = slope[node] * x + icpt[node];
    if (v > best) best = v;
    const mid = (lo + hi) >> 1;
    if (x <= mid) { node = left[node]; hi = mid; }
    else { node = right[node]; lo = mid + 1; }
  }
  return best;
}
const out = [];
let pos = 1;
for (let i = 0; i < q; i++) {
  if (tok[pos] === 1) { add(tok[pos + 1], tok[pos + 2]); pos += 3; }
  else { out.push(query(tok[pos + 1])); pos += 2; }
}
console.log(out.join('\n'));

