import java.io.*;
import java.util.*;

public class Main {
    static final int LO = -1000000, HI = 1000000;
    static long[] slope, icpt;
    static int[] left, right;
    static int count = 0;
    static int newNode(long m, long b) {
        slope[count] = m; icpt[count] = b; left[count] = -1; right[count] = -1;
        return count++;
    }
    static void add(long m, long b) {
        if (count == 0) { newNode(m, b); return; }
        int node = 0, lo = LO, hi = HI;
        while (true) {
            int mid = (lo + hi) >> 1;
            if (m * mid + b > slope[node] * mid + icpt[node]) {
                long t = slope[node]; slope[node] = m; m = t;
                t = icpt[node]; icpt[node] = b; b = t;
            }
            if (lo == hi) return;
            int[] side;
            if (m * lo + b > slope[node] * lo + icpt[node]) { side = left; hi = mid; }
            else if (m * hi + b > slope[node] * hi + icpt[node]) { side = right; lo = mid + 1; }
            else return;
            if (side[node] == -1) { side[node] = newNode(m, b); return; }
            node = side[node];
        }
    }
    static long query(long x) {
        int node = 0, lo = LO, hi = HI;
        long best = Long.MIN_VALUE;
        while (node != -1) {
            long v = slope[node] * x + icpt[node];
            if (v > best) best = v;
            int mid = (lo + hi) >> 1;
            if (x <= mid) { node = left[node]; hi = mid; }
            else { node = right[node]; lo = mid + 1; }
        }
        return best;
    }
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int q = (int) st.nval;
        slope = new long[q + 1]; icpt = new long[q + 1]; left = new int[q + 1]; right = new int[q + 1];
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            st.nextToken();
            int type = (int) st.nval;
            if (type == 1) {
                st.nextToken(); long m = (long) st.nval;
                st.nextToken(); long b = (long) st.nval;
                add(m, b);
            } else {
                st.nextToken();
                sb.append(query((long) st.nval)).append('\n');
            }
        }
        System.out.print(sb);
    }
}

