#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int LO = -1000000, HI = 1000000;
vector<ll> slope_, icpt;
vector<int> lc, rc;
int newNode(ll m, ll b) {
    slope_.push_back(m); icpt.push_back(b); lc.push_back(-1); rc.push_back(-1);
    return (int)slope_.size() - 1;
}
void add(ll m, ll b) {
    if (slope_.empty()) { newNode(m, b); return; }
    int node = 0, lo = LO, hi = HI;
    while (true) {
        int mid = (lo + hi) >> 1;
        if (m * mid + b > slope_[node] * mid + icpt[node]) { swap(m, slope_[node]); swap(b, icpt[node]); }
        if (lo == hi) return;
        vector<int> *side;
        if (m * lo + b > slope_[node] * lo + icpt[node]) { side = &lc; hi = mid; }
        else if (m * hi + b > slope_[node] * hi + icpt[node]) { side = &rc; lo = mid + 1; }
        else return;
        if ((*side)[node] == -1) { int id = newNode(m, b); (*side)[node] = id; return; }
        node = (*side)[node];
    }
}
ll query(ll x) {
    int node = 0, lo = LO, hi = HI;
    ll best = LLONG_MIN;
    while (node != -1) {
        best = max(best, slope_[node] * x + icpt[node]);
        int mid = (lo + hi) >> 1;
        if (x <= mid) { node = lc[node]; hi = mid; }
        else { node = rc[node]; lo = mid + 1; }
    }
    return best;
}
int main() {
    int q;
    scanf("%d", &q);
    while (q--) {
        int type;
        scanf("%d", &type);
        if (type == 1) { ll m, b; scanf("%lld %lld", &m, &b); add(m, b); }
        else { ll x; scanf("%lld", &x); printf("%lld\n", query(x)); }
    }
    return 0;
}
